static void dense(const float *x, int nin, const float *W, const float *b, int nout, float *y, int relu)
{
  for (int j = 0; j < nout; j++)
  {
    float s = b[j];
    for (int i = 0; i < nin; i++) { s += x[i] * W[i * nout + j]; }
    y[j] = (relu && s < 0.0f) ? 0.0f : s;
  }
}

int meteo_mlp_ref_predire(const float x_norm[METEO_MLP_NB_IN], float proba[METEO_MLP_NB_OUT])
{
  float a[32], b[32];
  const float *in = x_norm;
  dense(in, 14, &W0[0][0], B0, 32, a, 1);
  in = a;
  dense(in, 32, &W1[0][0], B1, 16, b, 1);
  in = b;
  dense(in, 16, &W2[0][0], B2, 3, proba, 0);
  /* softmax (stable) + argmax */
  float mx = proba[0]; int best = 0;
  for (int j = 1; j < METEO_MLP_NB_OUT; j++) { if (proba[j] > mx) { mx = proba[j]; best = j; } }
  float s = 0.0f;
  for (int j = 0; j < METEO_MLP_NB_OUT; j++) { proba[j] = expf(proba[j] - mx); s += proba[j]; }
  for (int j = 0; j < METEO_MLP_NB_OUT; j++) { proba[j] /= s; }
  return best;
}
